def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle all 9's case: next palindrome is 10..01
    if all(ch == '9' for ch in s):
        return num + 2  # e.g., 9->11, 99->101, 999->1001

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left_half = s[:half_len]

    # First try palindrome by mirroring left half
    candidate = make_palindrome(left_half, length % 2 == 1)
    if candidate > num:
        return candidate

    # If not greater, increment the left half and mirror again
    # Increment left_half as an integer
    incremented = str(int(left_half) + 1)

    # If length changes after increment (e.g. 999 -> 1000)
    if len(incremented) > len(left_half):
        # This means palindrome length increases by 1
        # For example 999 -> next palindrome is 1001
        return int('1' + ('0' * (length -1)) + '1')

    return make_palindrome(incremented, length % 2 == 1)


