def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, s1, t1 = extended_gcd(y, x % y)
        s = t1
        t = s1 - (x // y) * t1
        return gcd, s, t

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return "No solution"

    # scale initial solution
    x0 *= n // gcd
    y0 *= n // gcd

    # Coefficients for general solution
    a_div = a // gcd
    b_div = b // gcd

    # We want x >= 0 and y >= 0
    # General solutions: x = x0 + k * (b/gcd), y = y0 - k * (a/gcd)
    # Find k so that x >= 0:
    # x0 + k * b_div >= 0 => k >= -x0 / b_div
    # y >= 0:
    # y0 - k * a_div >= 0 => k <= y0 / a_div

    # k must be an integer in [ceil(-x0/b_div), floor(y0/a_div)]
    from math import ceil, floor

    low = ceil(-x0 / b_div)
    high = floor(y0 / a_div)

    if low > high:
        return "No solution"

    # We want smallest non-negative x, so pick k = low (smallest k to make x >= 0)
    k = low
    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        return "No solution"

    return ('x = ', x, ', y = ', y)


