def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i starting with x
    # Elements are from 1 to m.
    # next element >= 2 * previous element

    if n == 1:
        return m  # any starting element 1..m

    dp = [0] * (m + 2)  # 1-based indexing
    # Base case: sequences of length 1 starting at x = 1 for each x
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 2)
        # To optimize, we can use suffix sums to get sums over intervals
        # For each x, next element y >= 2*x
        # So new_dp[x] = sum of dp[y] for y in [2*x, m]

        suffix_sum = [0] * (m + 3)
        for i in range(m, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp[i]

        for x in range(1, m + 1):
            lo = 2 * x
            if lo > m:
                new_dp[x] = 0
            else:
                new_dp[x] = suffix_sum[lo]

        dp = new_dp

    return sum(dp[1:m + 1])


