def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    # If the array is not rotated (sorted ascending), the last element is max
    if nums[left] < nums[right]:
        return nums[right]
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than right, max is in right half
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left points to the smallest element (rotation point),
    # so max is element before it (handle wrap around)
    return nums[left - 1]


