def lucky_num(n):
    # Start with a list of odd numbers only (all lucky numbers are odd)
    numbers = list(range(1, 2 * n * 10, 2))
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element starting from index step-1
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx >= len(numbers):
            break
    return numbers[:n]


