def compute_Last_Digit(a: int, b: int) -> int:
    # The product is (a+1)*(a+2)*...*b
    # We need the last digit of this product.
    # If b <= a, the product is empty, so return 1 (the multiplicative identity).
    if b <= a:
        return 1

    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10
        # Once last_digit is zero, it will remain zero, so we can break early
        if last_digit == 0:
            break
    return last_digit


