def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # The next palindrome greater than a number like 9, 99, 999 ... is 10...01
        return num + 2  # e.g. 9->11, 99->101, 999->1001

    def make_palindrome(left, middle, odd_len):
        if odd_len:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    if odd_len:
        left = s[:length // 2]
        middle = s[length // 2]
    else:
        left = s[:length // 2]
        middle = ''

    # Construct palindrome by mirroring left (and middle if odd)
    palindrome = make_palindrome(left, middle, odd_len)

    if palindrome > num:
        return palindrome

    # Need to increment the middle part and construct palindrome again
    if odd_len:
        # Increment the middle digit plus left as a combined number
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)
        # If length changes, means carry overflowed, e.g. 999 -> 1000
        if len(left_middle_str) > len(left) + 1:
            # This means palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')
        left = left_middle_str[:-1]
        middle = left_middle_str[-1]
    else:
        # No middle digit, just increment left
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > length // 2:
            # Length increased, e.g. 99 -> 100, so palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')

    palindrome = make_palindrome(left, middle, odd_len)
    return palindrome


