def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            depth = 1 + dict_depth(v)
            if depth > max_depth:
                max_depth = depth
    return max_depth


