def remove_column(collection, position):
    outer_type = type(collection)
    result = []
    for inner in collection:
        inner_type = type(inner)
        if not (hasattr(inner, '__getitem__') and hasattr(inner, '__len__')):
            # If inner is not a sequence, just keep it as is
            result.append(inner)
            continue
        # Remove the element at position
        new_inner = inner[:position] + inner[position+1:]
        # Convert back to original inner type
        if inner_type is tuple:
            new_inner = tuple(new_inner)
        elif inner_type is list:
            new_inner = list(new_inner)
        else:
            # If inner is other sequence type, try to convert similarly
            try:
                new_inner = inner_type(new_inner)
            except Exception:
                # fallback to list if conversion fails
                new_inner = list(new_inner)
        result.append(new_inner)
    # Convert back to original outer type
    if outer_type is tuple:
        return tuple(result)
    elif outer_type is list:
        return list(result)
    else:
        try:
            return outer_type(result)
        except Exception:
            return result


