from typing import List, Dict, Any, Optional

def sum_column(grouped_data: Dict[Any, List[Dict[str, Any]]], group_key: Any, column: str) -> float:
    """
    Sum the values from a specified column in the group identified by group_key within grouped_data.

    Parameters:
    - grouped_data: dict mapping group keys to list of dicts (rows).
    - group_key: the key identifying the group to sum over.
    - column: the column name whose values to sum.

    Returns:
    - sum of all values in the specified column for the chosen group.
      If the group_key is not present or no values, returns 0.
      Non-numeric or missing values are skipped.
    """
    group = grouped_data.get(group_key, [])
    total = 0.0
    for row in group:
        value = row.get(column)
        if isinstance(value, (int, float)):
            total += value
    return total


