def lucky_num(n):
    # Start with a large enough list of odd numbers (lucky numbers are odd)
    # We start with 1 and odd numbers thereafter.
    # The size is heuristic; we increase if needed.
    size = max(2 * n * n, 10)  # heuristic initial size
    while True:
        nums = list(range(1, size + 1, 2))  # start with 1 and odd numbers only
        idx = 1  # index of the next sieve number (nums[0] = 1, skip it)
        while idx < len(nums):
            step = nums[idx]
            if step > len(nums):
                break
            # Remove every step-th number (1-based index)
            nums = [num for i, num in enumerate(nums, start=1) if i % step != 0]
            idx += 1
        if len(nums) >= n:
            return nums[:n]
        # If not enough lucky numbers, increase size and try again
        size *= 2


