def compute_Last_Digit(a: int, b: int) -> int:
    start = min(a, b) + 1
    end = max(a, b)
    if start > end:
        return 1  # empty product
    last_digit = 1
    for num in range(start, end + 1):
        last_digit = (last_digit * (num % 10)) % 10
        if last_digit == 0:
            return 0
    return last_digit


