def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares if and only if
    # n = a² - b² = (a-b)(a+b)
    # So n must be factored into two integers p and q such that n = p*q and p and q have the same parity.
    # Because (a-b) and (a+b) must be both integers and (a+b + a-b) = 2a, so p and q must be both even or both odd.
    # So check if n has any factor pairs with the same parity.
    if n == 0:
        return True
    abs_n = abs(n)
    for p in range(1, int(abs_n**0.5) + 1):
        if abs_n % p == 0:
            q = abs_n // p
            # Check if p and q have the same parity
            if (p % 2) == (q % 2):
                return True
    return False


