def zip_tuples(t1, t2):
    len1, len2 = len(t1), len(t2)
    if len1 == 0 and len2 == 0:
        return ()
    if len1 == 0:
        # cycle t1 elements is impossible; but per the task, cycle shorter tuple elements
        # here t1 is empty, so cycling is not possible, but we still must produce pairs
        # Since t1 is empty, no elements to pair, so no pairs possible
        # Return empty tuple or raise? The task implies cycling shorter tuple elements,
        # but length zero means no elements to cycle.
        # So we cannot produce pairs. Return empty tuple.
        return ()
    if len2 == 0:
        # same logic as above
        return ()
    max_len = max(len1, len2)
    return tuple((t1[i % len1], t2[i % len2]) for i in range(max_len))


