def next_smallest_palindrome(n: int) -> int:
    """
    Find the largest palindrome strictly less than n.
    """

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    for candidate in range(n - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate
    return -1  # if no palindrome found less than n (only if n <= 0)


