def find_solution(a: int, b: int, n: int):
    # Extended Euclidean Algorithm to find one solution (x0, y0) to a*x + b*y = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, x1, y1 = extended_gcd(y, x % y)
        return g, y1, x1 - (x // y) * y1

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None  # no solution

    # Scale the base solution to n
    x0 *= n // g
    y0 *= n // g

    # Coefficients for parameter t in general solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    a_div = a // g
    b_div = b // g

    # We want non-negative x and y:
    # x >= 0 => x0 + t*b_div >= 0 => t >= -x0/b_div
    # y >= 0 => y0 - t*a_div >= 0 => t <= y0/a_div

    # Calculate bounds for t
    from math import ceil, floor

    t_min = ceil(-x0 / b_div) if b_div != 0 else float('-inf')
    t_max = floor(y0 / a_div) if a_div != 0 else float('inf')

    if t_min > t_max:
        return None

    # Any integer t in [t_min, t_max] works, choose t = t_min (smallest t to get smallest x)
    t = t_min
    x = x0 + t * b_div
    y = y0 - t * a_div

    if x < 0 or y < 0:
        return None
    return (x, y)


