def get_total_number_of_sequences(max_element_value: int, sequence_length: int) -> int:
    if sequence_length == 0:
        return 0
    # dp[i][v] = number of sequences of length i ending with element v (1-based elements)
    dp = [ [0]*(max_element_value+1) for _ in range(sequence_length+1) ]
    # Base case: sequences of length 1
    for v in range(1, max_element_value+1):
        dp[1][v] = 1

    for i in range(2, sequence_length+1):
        for v in range(1, max_element_value+1):
            total = 0
            # Previous element u must be such that v == 2*u or u == 2*v
            if v % 2 == 0:
                u = v // 2
                if 1 <= u <= max_element_value:
                    total += dp[i-1][u]
            u = v * 2
            if 1 <= u <= max_element_value:
                total += dp[i-1][u]
            dp[i][v] = total

    return sum(dp[sequence_length][1:max_element_value+1])


