def smallest_missing(arr, low, high):
    # The function finds the smallest non-negative integer in [low, high+1]
    # that does NOT appear in arr[low:high+1].
    # arr is sorted, distinct, non-negative integers.

    # The index range is [low, high], so possible missing integers are in [low, high+1].

    # We'll do a binary search in the index range [low, high] to find the smallest missing integer.
    # The key insight:
    # If arr[mid] == mid, then all integers from low to mid are present at their indices, so search right.
    # Otherwise, the missing integer is at or before mid, so search left.

    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            left = mid + 1
        else:
            right = mid - 1
    return left


