def find_Max(nums):
    if not nums:
        return None  # or raise an error if preferred

    low, high = 0, len(nums) - 1

    # If array is not rotated (last element > first element), max is last element
    if nums[high] > nums[0]:
        return nums[high]

    while low < high:
        mid = (low + high) // 2
        # If mid element is greater than next element, mid is max
        if nums[mid] > nums[mid + 1]:
            return nums[mid]
        # If mid element is greater than first element, max is in right half
        if nums[mid] >= nums[0]:
            low = mid + 1
        else:
            high = mid

    # When low == high, max is at low-1 (because low points to min)
    return nums[low - 1]


