import re

def text_match(s):
    # pattern: 'a' followed by zero or more 'b's
    # the match should only succeed if no 'b' immediately follows the matched substring
    # so match 'a' + 'b'* and ensure the next character is not 'b' (or end of string)
    pattern = re.compile(r'a(b*)')
    for m in pattern.finditer(s):
        end = m.end()
        if end == len(s) or s[end] != 'b':
            return True
    return False


