def lucky_num(n):
    numbers = list(range(1, 5000, 2))  # start with odd numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx > n:  # just a heuristic to stop early if enough numbers
            break
    return numbers[:n]


