def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Edge case: if all digits are 9 (e.g. 9, 99, 999), the next palindrome is 10...01
    if all(ch == '9' for ch in s):
        return n + 2  # For 9 -> 11, 99 -> 101, 999 -> 1001, etc.

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Generate the palindrome by mirroring the left half onto the right half
    def make_palindrome(left: str, mid: str, odd_length: bool) -> str:
        if odd_length:
            return left + mid + left[::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    if odd_length:
        left = s[:length//2]
        mid = s[length//2]
        right = s[length//2+1:]
    else:
        left = s[:length//2]
        mid = ''
        right = s[length//2:]

    # Construct palindrome by mirroring left and mid
    p = make_palindrome(left, mid, odd_length)
    p_int = int(p)

    # If palindrome is greater than n, return it
    if p_int > n:
        return p_int

    # Otherwise increment the middle part and mirror again
    if odd_length:
        # Increment the middle digit with the left part as a number
        left_mid_num = int(left + mid)
        left_mid_num += 1
        left_mid_str = str(left_mid_num)
        # Handle length changes after increment
        if len(left_mid_str) > len(left) + 1:
            # This happens when 9...9 increments, e.g. 999 -> 1000
            # The palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')
        left = left_mid_str[:-1]
        mid = left_mid_str[-1]
        return int(make_palindrome(left, mid, True))
    else:
        # Even length: increment left half and mirror
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            # e.g. 99 -> 100 -> palindrome length increases
            return int('1' + ('0' * (length - 1)) + '1')
        return int(make_palindrome(left_str, '', False))


