def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, s, t = extended_gcd(y, x % y)
        return g, t, s - (x // y) * t

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return "No solution"
    x = x0 * (n // g)
    y = y0 * (n // g)
    return ('x = ', x, ', y = ', y)


