def get_total_number_of_sequences(m: int, n: int) -> int:
    """
    Counts the number of sequences of length n formed from integers 1 to m
    such that no two adjacent elements are equal.

    Parameters:
    m (int): number of possible values per element (values are from 1 to m)
    n (int): length of the sequence

    Returns:
    int: count of sequences of length n with no two adjacent elements equal
    """
    if n == 0:
        return 0
    if n == 1:
        return m
    # For n >= 2, total sequences = m * (m-1)^(n-1)
    return m * (m - 1) ** (n - 1)


