def min_flip_to_make_string_alternate(s: str) -> str:
    n = len(s)
    alt0 = []
    alt1 = []
    for i in range(n):
        alt0.append('0' if i % 2 == 0 else '1')
        alt1.append('1' if i % 2 == 0 else '0')
    alt0_str = ''.join(alt0)
    alt1_str = ''.join(alt1)

    # Count flips needed for each pattern
    flips0 = sum(s[i] != alt0_str[i] for i in range(n))
    flips1 = sum(s[i] != alt1_str[i] for i in range(n))

    # Return the alternate string requiring fewer flips; if tie, return alt0
    if flips0 <= flips1:
        return alt0_str
    else:
        return alt1_str


