def lucky_num(n):
    # Start with the initial list of odd numbers (including 1)
    numbers = list(range(1, 2 * n * 10, 2))
    idx = 1  # Start at index 1 (second element), which is the first "step" for elimination

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element from the list (1-based indexing)
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n:
            continue
        else:
            # If not enough numbers, extend the list with the next odd numbers
            last = numbers[-1]
            extension = list(range(last + 2, last + 2 + 2 * n * 10, 2))
            numbers.extend(extension)

    return numbers[:n]


