def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares a² - b² 
    # iff n is not congruent to 2 mod 4.
    # Explanation:
    # a² - b² = (a+b)(a-b).
    # Squares mod 4 are either 0 or 1.
    # Difference of squares mod 4 can be 0,1,3 but never 2.
    # Thus, if n % 4 == 2, return False; else True.
    return n % 4 != 2


