def next_smallest_palindrome(num: int) -> int:
    if num <= 0:
        # No palindrome less than 0 (assuming non-negative palindromes)
        return None

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # Start checking from num-1 downwards for the next palindrome
    for candidate in range(num - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate


