def smallest_missing(nums):
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] == mid:
            left = mid + 1
        elif nums[mid] > mid:
            right = mid
        else:
            # nums[mid] < mid is possible if there are negative numbers,
            # but since we want the smallest missing non-negative integer,
            # we ignore negative values by moving right pointer accordingly.
            right = mid
    return left


