def find_Max(arr):
    if not arr:
        return None
    low, high = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), max is last element
    if arr[low] < arr[high]:
        return arr[high]
    while low <= high:
        mid = (low + high) // 2
        # Check if mid is max
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # Check if mid-1 is max
        if mid > 0 and arr[mid - 1] > arr[mid]:
            return arr[mid - 1]
        # Decide which half to choose
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    return arr[0]  # fallback, array with one element


