def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of squares:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x * y
    # Since a and b are integers, x and y must be integers with the same parity (both even or both odd)
    # Also, y > x > 0 if n > 0, and if n < 0, swap roles.
    #
    # The problem reduces to: can n be factored into two integers x and y of the same parity?
    #
    # Special case: n = 0 -> 0 = a^2 - a^2, so True.

    if n == 0:
        return True

    # For n != 0, check all factor pairs of abs(n)
    abs_n = abs(n)
    from math import isqrt

    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check if x and y have same parity
            if (x % 2) == (y % 2):
                # For positive n, a = (y+x)//2, b = (y-x)//2 are integers
                # For negative n, one can consider swapping roles or equivalently check same parity condition
                return True
    return False


