def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all digits are '9', the next palindrome is 10...01 (length+1 digits)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, middle: str, length: int) -> int:
        if length % 2 == 0:
            return int(left + left[::-1])
        else:
            return int(left + middle + left[::-1])

    # Split the number into left, middle and right parts
    if length % 2 == 0:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]
    else:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]

    # Construct palindrome by mirroring left (with middle if odd length)
    palindrome = make_palindrome(left, middle, length)

    if palindrome > num:
        return palindrome

    # Need to increment the middle part and then mirror again
    if length % 2 == 0:
        # Even length: increment left as integer and mirror
        left_num = int(left) + 1
        left = str(left_num)
        # If increment causes length increase (e.g. 99->100), handle that
        if len(left) > length // 2:
            # e.g. 99 -> 100, palindrome length increases by 1 (from even to odd)
            # So palindrome is 10...01
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = make_palindrome(left, '', length)
    else:
        # Odd length: increment the middle digit + left as a combined string
        left_middle_num = int(left + middle) + 1
        left_middle_str = str(left_middle_num)
        if len(left_middle_str) > len(left) + 1:
            # e.g. 999 -> 1000, palindrome length increases
            return int('1' + ('0' * (length - 1)) + '1')
        left = left_middle_str[:-1]
        middle = left_middle_str[-1]
        palindrome = make_palindrome(left, middle, length)

    return palindrome


