def find_solution(a: int, b: int, n: int):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, s, t = extended_gcd(y, x % y)
        return g, t, s - (x // y) * t

    # Handle the special case when both a and b are zero
    if a == 0 and b == 0:
        if n == 0:
            # Infinite solutions, but return one trivial solution
            return ('x = ', 0, ', y = ', 0)
        else:
            return 'No solution'

    g, x0, y0 = extended_gcd(abs(a), abs(b))

    if n % g != 0:
        return 'No solution'

    mult = n // g
    x = x0 * mult
    y = y0 * mult

    # Restore the sign of x and y depending on signs of a and b
    if a < 0:
        x = -x
    if b < 0:
        y = -y

    return ('x = ', x, ', y = ', y)


