def get_total_number_of_sequences(n: int, m: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length, prev):
        if length == n:
            return 1
        total = 0
        start = 2 * prev
        # Elements are positive integers <= m
        if start > m:
            return 0
        for next_val in range(start, m + 1):
            total += count_sequences(length + 1, next_val)
        return total

    total_sequences = 0
    # First element can be any positive integer <= m
    for first in range(1, m + 1):
        total_sequences += count_sequences(1, first)
    return total_sequences


