def smallest_missing(arr):
    """
    Given a sorted list of integers, return the smallest missing positive integer starting from 1.
    """
    expected = 1
    for num in arr:
        if num == expected:
            expected += 1
        elif num > expected:
            # We found a gap
            break
    return expected


