def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is now the index of the smallest element
    # The largest element is just before it, or at the end if left == 0
    return nums[left - 1] if left > 0 else nums[-1]


