def filter_data(data, criteria):
    """
    Filter measurements of people stored in a dictionary.

    Parameters:
    - data: dict of person -> list of measurements (e.g. {'a': [5, 2], 'b': [3, 7]}).
    - criteria: a function that takes a measurement and returns True if it should be kept.

    Returns:
    - dict of person -> list of measurements filtered by criteria.
      Persons with no measurements passing the filter are excluded.
    """
    return {person: [m for m in measurements if criteria(m)]
            for person, measurements in data.items()
            if any(criteria(m) for m in measurements)}


