def substract_elements(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        keys = a.keys() & b.keys()
        # Preserve keys common to both, subtract corresponding values recursively
        return {k: substract_elements(a[k], b[k]) for k in keys}
    elif isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        # Preserve type and length, subtract element-wise
        length = min(len(a), len(b))
        result = [substract_elements(a[i], b[i]) for i in range(length)]
        return type(a)(result)
    else:
        # Base case: subtract numeric elements
        return a - b


