def get_noOfways(n: int, m: int) -> int:
    # Here m is unused because the problem clarified:
    # We tile a 2 x n board with 2 x 1 dominoes.
    # The number of ways to tile a 2 x n board with 2 x 1 dominoes is given by the (n+1)-th Fibonacci number.
    # Base cases:
    if n == 0:
        return 1  # empty board, 1 way (do nothing)
    if n == 1:
        return 1  # only vertical dominoes

    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1

    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]


