def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        # factorial(b)//factorial(a) is zero since b! < a!, integer division is zero
        return 0
    # factorial(b)//factorial(a) = (a+1)*(a+2)*...*b
    result = 1
    for x in range(a + 1, b + 1):
        result *= x
        result %= 10  # keep only last digit to avoid large numbers
    return result


