def dif_Square(n: int) -> bool:
    # Any integer n can be represented as a difference of squares a^2 - b^2
    # if and only if n % 4 != 2.
    # This follows from the identity:
    # a^2 - b^2 = (a+b)(a-b)
    # Squares mod 4 are 0 or 1, so difference of squares mod 4 can be 0, 1, or 3 but never 2.
    return n % 4 != 2


