def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle single digit numbers quickly:
    if num < 8:
        return num + 1

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, then the next palindrome is 10..01 with length+1 digits
    if is_all_nines(s):
        return int("1" + ("0" * (length - 1)) + "1")

    # Construct palindrome by mirroring left half to right half
    def make_palindrome(left, middle, length):
        if length % 2 == 0:
            return int(left + left[::-1])
        else:
            return int(left + middle + left[::-1])

    half_len = length // 2
    if length % 2 == 0:
        left = s[:half_len]
        middle = ''
        palindrome = int(left + left[::-1])
        if palindrome > num:
            return palindrome
        # increment left half and mirror again
        left_inc = str(int(left) + 1)
        # If increment leads to length change (like 99->100)
        if len(left_inc) > len(left):
            # Example: 99 -> 100, length increases, so palindrome is 100001 for length 6
            return int("1" + ("0" * (length - 1)) + "1")
        return int(left_inc + left_inc[::-1])
    else:
        left = s[:half_len]
        middle = s[half_len]
        palindrome = int(left + middle + left[::-1])
        if palindrome > num:
            return palindrome
        # increment the middle digit + left half as a whole number
        left_middle_num = int(left + middle)
        left_middle_inc = str(left_middle_num + 1)
        # If increment leads to length change (e.g. 999 -> 1000)
        if len(left_middle_inc) > len(left + middle):
            # e.g. from 999 -> 1000, palindrome becomes 1000001 (length+1 digits)
            return int("1" + ("0" * (length - 1)) + "1")
        new_left = left_middle_inc[:-1]
        new_middle = left_middle_inc[-1]
        return int(new_left + new_middle + new_left[::-1])


