def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd and one solution (x0, y0) to a*x + b*y = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return 'No solution'
    # Scale the initial solution to n
    x0 *= n // gcd
    y0 *= n // gcd

    # General solution:
    # x = x0 + k*(b/gcd)
    # y = y0 - k*(a/gcd)
    # We want smallest non-negative x:
    b_div = b // gcd
    a_div = a // gcd

    # Find k so that x >= 0 and x is minimal non-negative
    # x = x0 + k*b_div >= 0 => k >= (-x0)/b_div
    # k can be positive or negative depending on sign of b_div

    # Compute k candidate:
    # k = ceil(-x0 / b_div) if b_div > 0 else floor(-x0 / b_div)

    if b_div > 0:
        k = (-x0 + b_div - 1) // b_div  # ceil division for positive divisor
    else:
        # b_div < 0
        # ceil(-x0 / b_div) when b_div<0 is floor(-x0 / b_div)
        # floor division for negative divisor:
        k = (-x0) // b_div

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0:
        return 'No solution'
    return (x, y)


