from typing import List, Union

def below_zero(operations: Union[List[int], str]) -> Union[bool, List[bool]]:
    if isinstance(operations, str):
        # Convert string to list of integers (each char to int)
        ops = [int(ch) for ch in operations]
        # For each prefix, compute cumulative sum and check if any below zero
        # Return list of booleans indicating if balance fell below zero at that prefix
        # Since no loops allowed, use map with a helper
        from itertools import accumulate
        balances = list(accumulate(ops))
        # For each prefix, check if any balance < 0
        def fell_below_zero_up_to(i):
            return any(b < 0 for b in balances[:i+1])
        return [any(b < 0 for b in balances[:i+1]) for i in range(len(balances))]
    else:
        # For list input: check if any prefix sum < 0
        from itertools import accumulate
        balances = list(accumulate(operations))
        if any(b < 0 for b in balances):
            return True
        else:
            return False


