from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input: string of groups of parentheses separated by spaces.
    Output: list of integers representing max nesting depth for each group.
    No loops or recursion.
    """
    groups = paren_string.split()

    def max_depth(s: str) -> int:
        # Map each character to +1 for '(' and -1 for ')'
        depths = list(map(lambda c: 1 if c == '(' else -1, s))
        # Calculate prefix sums of depths to get nesting levels
        prefix_sums = list(map(lambda i: sum(depths[:i+1]), range(len(depths))))
        return max(prefix_sums) if prefix_sums else 0

    return list(map(max_depth, groups))


