from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    notes = music_string.split()
    beats_list = list(map(beats_map.get, notes, []))
    # Count occurrences carefully:
    # Using split, count how many times each note appears exactly:
    count_o = notes.count('o')
    count_o_bar = notes.count('o|')
    count_dot_bar = notes.count('.|')

    counts = {'o': count_o, 'o|': count_o_bar, '.|': count_dot_bar}

    # If all counts are zero (empty input), return empty list and empty string
    if count_o + count_o_bar + count_dot_bar == 0:
        return [], ''

    # Determine most common note, break ties by longer beat duration
    sorted_notes = sorted(counts.items(), key=lambda x: (x[1], beats_map[x[0]]), reverse=True)
    most_common = sorted_notes[0][0]

    return beats_list, most_common


