def monotonic(l):
    if isinstance(l, list):
        # For lists: duplicates allowed, non-decreasing or non-increasing sequences, return only bool
        if len(l) < 2:
            return True
        # Check non-decreasing
        def non_decreasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] <= l[i+1] and non_decreasing(i+1)
        # Check non-increasing
        def non_increasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] >= l[i+1] and non_increasing(i+1)
        return non_decreasing() or non_increasing()
    else:
        # For strings: duplicates not allowed, strictly alphabetical or reverse alphabetical order, return (bool, str)
        s = l
        if len(s) < 2:
            return True, s
        # Check duplicates (no duplicates allowed)
        if len(set(s)) != len(s):
            return False
        # Check strictly increasing (alphabetical)
        def strictly_increasing(i=0):
            if i == len(s) - 1:
                return True
            return s[i] < s[i+1] and strictly_increasing(i+1)
        # Check strictly decreasing (reverse alphabetical)
        def strictly_decreasing(i=0):
            if i == len(s) - 1:
                return True
            return s[i] > s[i+1] and strictly_decreasing(i+1)
        ok = strictly_increasing() or strictly_decreasing()
        return (ok, s) if ok else False


