def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        rev = s[::-1]
        return rev, int(rev)
    shift %= n
    if shift == 0:
        return s, int(s)
    shifted = s[-shift:] + s[:-shift]
    return shifted, int(shifted)


