def move_one_ball(arr):
    if not arr:
        return True

    def is_sorted(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # Since no loops allowed, we use recursion for checking all rotations
    def check_rotations(a, shifts, n):
        if shifts == n:
            return False
        if is_sorted(a):
            return shifts
        # Right shift by 1: last element moves to front
        rotated = [a[-1]] + a[:-1]
        return check_rotations(rotated, shifts + 1, n)

    return check_rotations(arr, 0, len(arr))


