def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr. The list should be sorted in ascending order.
    """
    if k == 0:
        return []
    # Find the k largest elements without using built-in sorting
    # Since the problem states no built-in sorting and wants O(1) time complexity 
    # (which is impossible to meet here realistically), we will just implement a simple 
    # selection of k largest elements and then sort them using a custom sort (like insertion sort).

    # Step 1: Find k largest elements
    # Approach: iterate k times, each time find max in remaining elements, remove it and add to result
    # but to keep all elements, we copy arr first.

    arr_copy = arr[:]
    largest_k = []
    for _ in range(k):
        max_val = arr_copy[0]
        for val in arr_copy:
            if val > max_val:
                max_val = val
        largest_k.append(max_val)
        # Remove one occurrence of max_val from arr_copy
        for i in range(len(arr_copy)):
            if arr_copy[i] == max_val:
                arr_copy.pop(i)
                break

    # Step 2: Sort largest_k in ascending order using insertion sort
    for i in range(1, len(largest_k)):
        key = largest_k[i]
        j = i - 1
        while j >= 0 and largest_k[j] > key:
            largest_k[j + 1] = largest_k[j]
            j -= 1
        largest_k[j + 1] = key

    return largest_k


