def digits(n):
    s = str(n)
    odd_digits = [int(d) for d in s if int(d) % 2 == 1]
    even_digits = [int(d) for d in s if int(d) % 2 == 0]

    if not odd_digits:
        # all digits are even
        return 0
    if not even_digits:
        # all digits are odd
        return 1

    from math import prod
    # Return product of odd digits only, per example digits(235)==15 (2*3*5=30 is wrong)
    return prod(odd_digits)


