def solve(s):
    if any(c.isalpha() for c in s):
        # Contains letters: toggle case of letters, keep others as is
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        # No letters: reverse string and return as int
        # Since input is numeric string, reversed string is also numeric
        return int(s[::-1])


