def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits left or right by shift
    and return the result as a string.
    A positive shift rotates digits to the right, negative shift rotates digits to the left.
    The output string does not include the sign.
    """
    digits = str(abs(x))
    n = len(digits)
    if n == 0:
        return ""
    shift = shift % n  # normalize shift to range [0, n-1]
    if shift == 0:
        return digits
    # positive shift: rotate right
    # negative shift already handled by modulo above and means rotate left
    return digits[-shift:] + digits[:-shift]


