def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit is negated
            first_digit = -int(s[1])
            rest = s[2:]
            rest_sum = sum(int(d) for d in rest)
            return first_digit + rest_sum
        else:
            return sum(int(d) for d in s)
    return sorted(nums, key=lambda x: digit_sum(x))


