def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since elements are unique, sorted array will be strictly increasing
    sorted_arr = sorted(arr)

    # We want to know if arr is a rotation of sorted_arr
    # A rotation can be checked by finding the index in arr where sorted_arr[0] occurs,
    # then checking if shifting arr starting from that index matches sorted_arr.

    try:
        start = arr.index(sorted_arr[0])
    except ValueError:
        # sorted_arr[0] must be in arr since they have same elements, but just in case
        return False

    for i in range(n):
        if arr[(start + i) % n] != sorted_arr[i]:
            return False
    return True


