def max_fill(grid, capacity):
    import math

    # Count water units in each well (row)
    water_counts = [sum(row) for row in grid]

    # The number of bucket lowerings is the maximum number of buckets needed for any single well,
    # because buckets can be lowered simultaneously across wells.
    # For each well, calculate how many times the bucket must be lowered:
    # ceil(water_units / capacity)
    if not water_counts:
        return 0

    max_lowerings = 0
    for count in water_counts:
        lowerings = math.ceil(count / capacity)
        if lowerings > max_lowerings:
            max_lowerings = lowerings

    return max_lowerings


