def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr.

    The returned list is sorted in ascending order.

    Args:
        arr (List[int]): The list of integers.
        k (int): The number of maximum elements to return.

    Returns:
        List[int]: Sorted list of the k largest numbers.
    """
    return sorted(arr)[-k:] if k > 0 else []


