def parse_music(music_string: str) -> List[int]:
    A, B, C = 4, 2, 1
    tokens = music_string.split()
    result = []
    for token in tokens:
        if token == 'o':
            result.append(A)
        elif token == 'o|':
            result.append(B)
        elif token == '.|':
            result.append(C)
        else:
            # If any unknown token appears, raise an error
            raise ValueError(f"Unknown note token: {token}")
    return result


