def parse_music(s: str) -> list[int]:
    duration_map = {
        'w': 4,   # whole note
        'h': 2,   # half note
        'q': 1,   # quarter note
        'e': 0.5, # eighth note
        's': 0.25 # sixteenth note
    }
    result = []
    for symbol in s.split():
        if symbol in duration_map:
            result.append(duration_map[symbol])
        else:
            # If unknown symbol, treat as 0 beats (or omit? Task doesn't say.)
            # We'll omit unknown symbols.
            pass
    return result


