def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Since all items are distinct, we can check the number of "drops" (arr[i] > arr[i+1])
    # in the array. If the array can be rotated to become sorted non-decreasingly,
    # then there can be at most one such drop.
    drops = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True


