def move_one_ball(seq):
    if not seq:
        return True
    n = len(seq)
    # Since elements are distinct, check how many "drops" in order there are
    drops = 0
    for i in range(n):
        if seq[i] > seq[(i+1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True


