def solve(seq):
    has_ascii_letter = any(('a' <= c <= 'z') or ('A' <= c <= 'Z') for c in seq)
    if not has_ascii_letter:
        return seq[::-1]
    result = []
    for c in seq:
        if 'a' <= c <= 'z':
            result.append(c.upper())
        elif 'A' <= c <= 'Z':
            result.append(c.lower())
        else:
            result.append(c)
    return ''.join(result)


