def anti_shuffle(s):
    import re
    def sort_word(word):
        # Separate trailing non-alphabetic characters (punctuation) from the word
        m = re.match(r'^([A-Za-z]+)([^A-Za-z]*)$', word)
        if m:
            core, tail = m.groups()
            sorted_core = ''.join(sorted(core))
            return sorted_core + tail
        else:
            # If no alphabetic characters, return as is
            return word

    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            # spaces as is
            result.append(token)
        else:
            result.append(sort_word(token))
    return ''.join(result)


