def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit after '-' is negative
            first_digit = -int(s[1])
            rest = s[2:]
            rest_sum = sum(int(ch) for ch in rest)
            return first_digit + rest_sum
        else:
            return sum(int(ch) for ch in s)
    return sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0])) and [x[1] for x in sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))]


