def anti_shuffle(s):
    import re

    # Split string into tokens of either spaces or non-space sequences
    tokens = re.findall(r'\s+|\S+', s)

    result_tokens = []
    for token in tokens:
        if token.isspace():
            # Keep spaces as is
            result_tokens.append(token)
        else:
            # Sort characters of the token (letters + punctuation)
            sorted_token = ''.join(sorted(token))
            result_tokens.append(sorted_token)

    return ''.join(result_tokens)


