def circular_shift(x, shift):
    """Circular shift the digits of the integer x to the right by shift positions,
    return the result as a string, preserving leading zeros.
    Negative x is handled by rotating the digits of the absolute value, then
    prefixing the result with '-'."""
    s = str(abs(x))
    n = len(s)
    if n == 0:
        return s
    shift %= n
    shifted = s[-shift:] + s[:-shift] if shift else s
    return ('-' if x < 0 else '') + shifted


