def move_one_ball(arr):
    if not arr:
        return True
    sorted_arr = sorted(arr)
    n = len(arr)
    # Try all possible right shifts of sorted_arr to see if any matches arr
    for shift in range(n):
        # Right shift sorted_arr by 'shift' positions
        # Right shift means last element moves to front
        shifted = sorted_arr[-shift:] + sorted_arr[:-shift]
        if shifted == arr:
            return True
    return False


