def max_fill(grid, capacity):
    """
    Given a grid of wells (each row is a well),
    where each 1 represents a unit of water,
    and a bucket capacity,
    return the maximum number of full buckets that can be filled
    by distributing water units from all wells combined,
    with the constraint that buckets can only be filled from one well each,
    but leftover water units from wells can be combined optimally.

    Explanation:
    - Each well can fill some number of full buckets by itself (floor(water_units / capacity)).
    - The leftover water units (water_units % capacity) cannot fill a bucket on their own,
      but leftovers from different wells can be combined to fill additional full buckets.
    - So total buckets = sum of floor divisions + floor of (sum of leftovers / capacity).
    """
    total_full_buckets = 0
    total_leftover = 0
    for row in grid:
        water_units = sum(row)
        full_buckets = water_units // capacity
        leftover = water_units % capacity
        total_full_buckets += full_buckets
        total_leftover += leftover

    total_full_buckets += total_leftover // capacity
    return total_full_buckets


