def prime_length(s: str) -> bool:
    """Write a function that takes a string and returns if the string
    length is a prime number or not.
    """
    length = len(s)
    if length < 2:
        return False
    if length == 2:
        return True
    if length % 2 == 0:
        return False
    for i in range(3, int(length ** 0.5) + 1, 2):
        if length % i == 0:
            return False
    return True


