import re

def anti_shuffle(s):
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            result.append(part)
        else:
            # sort characters ascending by ASCII
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)


