def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Check if array is already sorted non-decreasing or non-increasing
    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    def is_non_increasing(a):
        return all(a[i] >= a[i+1] for i in range(len(a)-1))

    if is_non_decreasing(arr) or is_non_increasing(arr):
        # If already sorted, return False as per the example logic:
        # Because it means we don't need to do any right shift to get sorted.
        # The example move_one_ball([3,4,5,1,2]) returns False when it can be sorted by right shifts,
        # so if already sorted, no right shifts needed, return False.
        return False

    # Try all right shifts, if any produces sorted array, return False (per example logic)
    # else return True.
    # Because if it can be sorted by right shifts, return False,
    # if it cannot, return True.
    for shift in range(1, n):
        shifted = arr[-shift:] + arr[:-shift]
        if is_non_decreasing(shifted) or is_non_increasing(shifted):
            return False

    return True


