def max_fill(grid, capacity):
    import math
    total_lowerings = 0
    for row in grid:
        water_units = sum(row)
        # Number of lowers for this well
        lowers = math.ceil(water_units / capacity) if water_units > 0 else 1
        total_lowerings += lowers
    return total_lowerings


